import { createAsyncThunk } from "@reduxjs/toolkit";
import { callApi } from "../../../../host/server/call-api.js";
import { toast } from "../../../../host/notify.js";
import {
  addInboxItem,
  confirmInboxItem,
  failInboxItem,
  setInboxItemText,
  removeInboxItem,
  hydrateInboxItems
} from "./inbox.slice.js";
import { classifyInboxEnqueueFailure } from "./inbox-error.js";
import { appendToComposerDraft } from "../instance-user-input/append-to-composer-draft.thunk.js";
const localInjectionId = () => `inbox_local_${crypto.randomUUID()}`;
const deliveryForMode = {
  queue: "turn_end",
  steer: "next_boundary"
};
const modeForDelivery = (delivery) => delivery === "turn_end" ? "queue" : "steer";
const promoteQueuedToSteer = createAsyncThunk(
  "conversationInbox/promoteQueuedToSteer",
  async ({ conversationId, injectionId }, { dispatch, getState }) => {
    const item = getState().conversationInbox?.byConversationId[conversationId]?.find((i) => i.injectionId === injectionId);
    if (!item || item.mode !== "queue" || item.status !== "pending") return;
    const outcome = await dispatch(
      retractInboxItem({ conversationId, injectionId })
    ).unwrap();
    if (outcome !== "retracted") return;
    await dispatch(
      enqueueInboxMessage({ conversationId, text: item.text, mode: "steer" })
    );
  }
);
const enqueueInboxMessage = createAsyncThunk(
  "conversationInbox/enqueue",
  async ({
    conversationId,
    text,
    mode = "queue",
    kind = "user_message",
    isVisibleToUser = true
  }, thunkApi) => {
    const { dispatch } = thunkApi;
    const localId = localInjectionId();
    dispatch(
      addInboxItem({
        injectionId: localId,
        conversationId,
        mode,
        kind,
        text,
        status: "sending",
        isVisibleToUser,
        queuedAt: (/* @__PURE__ */ new Date()).toISOString()
      })
    );
    const result = await dispatch(
      callApi({
        path: "/ai/conversations/{conversation_id}/inbox",
        method: "POST",
        pathParams: { conversation_id: conversationId },
        expectedErrorStatuses: [404],
        body: {
          kind,
          text,
          delivery: deliveryForMode[mode],
          is_visible_to_user: isVisibleToUser,
          is_visible_to_model: true
        }
      })
    );
    if (result.error) {
      const failure = classifyInboxEnqueueFailure(result.error);
      if (failure.reportAsSystemError) {
        console.error("[inbox] enqueue failed", {
          conversationId,
          error: result.error
        });
      }
      if (kind === "user_message" && isVisibleToUser) {
        dispatch(removeInboxItem({ conversationId, injectionId: localId }));
        dispatch(appendToComposerDraft(conversationId, text));
        toast[failure.toastSeverity]("Couldn't queue your message", {
          description: `${failure.message} Your message is back in the box.`
        });
      } else {
        dispatch(
          failInboxItem({
            conversationId,
            injectionId: localId,
            error: failure.message
          })
        );
        toast[failure.toastSeverity]("Couldn't queue your message", {
          description: failure.message
        });
      }
      return thunkApi.rejectWithValue(failure.message);
    }
    const data = result.data;
    dispatch(
      confirmInboxItem({
        conversationId,
        localId,
        injectionId: data.injection_id
      })
    );
    return { injectionId: data.injection_id, runActive: data.run_active };
  }
);
const retractInboxItem = createAsyncThunk(
  "conversationInbox/retract",
  async ({ conversationId, injectionId }, { dispatch }) => {
    if (injectionId.startsWith("inbox_local_")) {
      dispatch(removeInboxItem({ conversationId, injectionId }));
      return "retracted";
    }
    const result = await dispatch(
      callApi({
        path: "/ai/conversations/{conversation_id}/inbox/{injection_id}",
        method: "DELETE",
        pathParams: {
          conversation_id: conversationId,
          injection_id: injectionId
        }
      })
    );
    if (result.error && result.error.status === 409) {
      dispatch(removeInboxItem({ conversationId, injectionId }));
      toast.info("Already delivered", {
        description: "The agent picked this message up before it could be withdrawn."
      });
      return "already_drained";
    }
    if (result.error && result.error.status !== 404) {
      toast.error("Couldn't withdraw the queued message", {
        description: result.error.message ?? void 0
      });
      return "error";
    }
    dispatch(removeInboxItem({ conversationId, injectionId }));
    return "retracted";
  }
);
const editInboxItem = createAsyncThunk(
  "conversationInbox/edit",
  async ({ conversationId, injectionId, text }, { dispatch }) => {
    if (injectionId.startsWith("inbox_local_")) {
      dispatch(setInboxItemText({ conversationId, injectionId, text }));
      return;
    }
    const result = await dispatch(
      callApi({
        path: "/ai/conversations/{conversation_id}/inbox/{injection_id}",
        method: "PATCH",
        pathParams: {
          conversation_id: conversationId,
          injection_id: injectionId
        },
        body: { text }
      })
    );
    if (result.error && result.error.status === 409) {
      dispatch(removeInboxItem({ conversationId, injectionId }));
      toast.info("Already delivered", {
        description: "The agent picked this message up before the edit landed."
      });
      return;
    }
    if (result.error) {
      toast.error("Couldn't edit the queued message", {
        description: result.error.message ?? void 0
      });
      return;
    }
    dispatch(setInboxItemText({ conversationId, injectionId, text }));
  }
);
const hydrateInbox = createAsyncThunk("conversationInbox/hydrate", async ({ conversationId }, { dispatch }) => {
  const result = await dispatch(
    callApi({
      path: "/ai/conversations/{conversation_id}/inbox",
      method: "GET",
      pathParams: { conversation_id: conversationId },
      queryParams: { status: "pending" }
    })
  );
  if (result.error) {
    console.warn("[inbox] hydrate failed (best-effort)", {
      conversationId,
      error: result.error
    });
    return;
  }
  const wire = result.data ?? [];
  const items = wire.map((w) => ({
    injectionId: w.injection_id,
    conversationId,
    mode: modeForDelivery(w.delivery),
    kind: w.kind ?? "user_message",
    text: w.text ?? "",
    status: "pending",
    isVisibleToUser: w.is_visible_to_user ?? true,
    queuedAt: w.queued_at ?? (/* @__PURE__ */ new Date()).toISOString(),
    source: w.source ?? null
  }));
  dispatch(hydrateInboxItems({ conversationId, items }));
});
const returnQueuedToComposer = createAsyncThunk(
  "conversationInbox/returnQueuedToComposer",
  async ({ conversationId }, { dispatch, getState }) => {
    const waiting = (getState().conversationInbox?.byConversationId[conversationId] ?? []).filter(
      (item) => item.mode === "queue" && item.kind === "user_message" && item.status === "pending" && item.isVisibleToUser && item.source !== "agent_collab"
    );
    if (waiting.length === 0) return 0;
    const returned = [];
    for (const item of waiting) {
      const outcome = await dispatch(
        retractInboxItem({ conversationId, injectionId: item.injectionId })
      ).unwrap();
      if (outcome === "retracted") returned.push(item.text);
    }
    if (returned.length === 0) return 0;
    const { setUserInputText } = await import("../instance-user-input/instance-user-input.slice.js");
    const draft = getState().instanceUserInput?.byConversationId[conversationId]?.text ?? "";
    const text = [draft.trim() ? draft : null, ...returned].filter((part) => part !== null).join("\n\n");
    dispatch(setUserInputText({ conversationId, text }));
    return returned.length;
  }
);
export {
  editInboxItem,
  enqueueInboxMessage,
  hydrateInbox,
  promoteQueuedToSteer,
  retractInboxItem,
  returnQueuedToComposer
};
